#include <bits/stdc++.h>
using namespace std;
struct Fenwick {
    int n;
    vector < long long > b;
    Fenwick(int n) : n(n), b(n + 1) {
    }
    void add(int i, long long x) {
        for (; i <= n; i += i & - i) b [i] += x;
    }
    long long sum(int i) {
        long long s = 0;
        for (; i > 0; i -= i & - i) s += b [i];
        return s;
    }
}
;
int main() {
