class DSU:
    def __init__(self, n):
        self.p = list(range(n))
        self.sz = [1] * n
    def f(self, x):
        while x != self.p[x]:
            self.p[x] = self.p[self.p[x]]
            x = self.p[x]
        return x
    def u(self, a, b):
        a, b = (self.f(a), self.f(b))
        if a == b:
            return False
        if self.sz[a] < self.sz[b]:
            a, b = (b, a)
        self.p[b] = a
        self.sz[a] += self.sz[b]
        return True
