    for v in range(n):
        up[k][v] = up[k - 1][up[k - 1][v]]
def lca(a, b):
    if dep[a] < dep[b]:
        a, b = (b, a)
    diff = dep[a] - dep[b]
    for k in range(LOG):
        if diff >> k & 1:
            a = up[k][a]
    if a == b:
        return a
    for k in range(LOG - 1, -1, -1):
        if up[k][a] != up[k][b]:
            a = up[k][a]
            b = up[k][b]
    return up[0][a]
